      status = CASE WHEN corpus = voice_current_corpus(t.actor_id) THEN 'draft' ELSE 'stale' END, updated_at = clock_timestamp()
    WHERE id = (p_result->>'versionId')::uuid AND actor_id = t.actor_id AND status = 'generating';
END $function$;
